#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto do_op=[&](int x, int y){
        assert(x>=0 && y>=0 && x+y<n && (x>0||y>0));
        ops.push_back({x,y});
        vector<int> np(n);
        // suffix of length y: p[n-y..n-1] -> positions 0..y-1
        for(int i=0;i<y;i++) np[i]=p[n-y+i];
        // middle: p[x..n-y-1] -> positions y..n-x-1
        for(int i=x;i<n-y;i++) np[y+i-x]=p[i];
        // prefix of length x: p[0..x-1] -> positions n-x..n-1
        for(int i=0;i<x;i++) np[n-x+i]=p[i];
        p=np;
    };

    for(int i=0;i<n-1;i++){
        // Find where value (i+1) is
        int j=-1;
        for(int k=0;k<n;k++) if(p[k]==i+1){j=k;break;}
        if(j==i) continue;

        // We want to move p[j] to position i.
        // Elements at positions 0..i-1 are already sorted, must not disturb them.

        // Step 1: Move target to position 0 (if not already there)
        if(j>0){
            // op(j, 0): moves prefix of length j to end, middle p[j..n-1] to front
            // But we can also use: op(0, n-j) moves suffix of length n-j to front
            // suffix = p[j..n-1], middle = p[0..j-1] (empty if j=0), prefix empty
            // Result: p[j..n-1], p[0..j-1]. Target at position 0. 
            // But this disturbs positions 0..i-1!
            // We need: positions 0..i-1 stay as they are.

            // Alternative: op(i, n-j) if i + (n-j) < n, i.e., j > i. Which is true since j>=i+1>i (j!=i).
            // Wait j could equal i... no we checked j==i continue.
            // j > i guaranteed? j >= 0 but target is i+1 which hasn't been placed yet, and 0..i-1 have values 1..i. So j >= i, and j != i, so j > i. Good.

            if(i + (n-j) < n){ // j > i, always true since j>i means n-j < n-i, so i+(n-j) < n. Yes!
                do_op(i, n-j);
                // Result: [suffix=p[j..n-1]], [middle=p[i..j-1]], [prefix=p[0..i-1]]
                // Target (was p[j]) is now at position 0.
                j=0;
            }
        }

        // Step 2: Move target from position 0 to position i
        if(j==0 && i>0){
            // op(1, n-1-i): need 1+(n-1-i) < n => n-i < n => i>0. True.
            // suffix=p[n-1-i+1..n-1]=p[n-i..n-1], middle=p[1..i], prefix=p[0]
            // prefix p[0] goes to position n-1. Middle p[1..i] at positions n-1-i..n-2. 
            // Suffix p[n-i..n-1] at positions 0..i-1. target at pos n-1.
            // Hmm that's not right either. Let me just move to pos i:
            do_op(1, n-1-i);
            // Now target is at position n-1. 
            // op(n-1-i, 1): suffix=p[n-1], middle=p[n-1-i..n-2], prefix=p[0..n-2-i]
            do_op(n-1-i, 1);
            // target at pos 0, then prefix goes to end... let me just simulate.
        } else if(j==0 && i==0){
            // already done
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
